import sys


def main():
    text = sys.stdin.read()
    config, queries_part = text.partition("===\n")
    queries = queries_part.strip().splitlines() if queries_part else []

    data = {}
    current_section = ""
    for line in config.splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith(";"):
            continue
        if line.startswith("["):
            current_section = line[1:-1]
            continue
        key, value = line.split("=", 1)
        key = key.strip()
        value = value.strip()
        if current_section:
            if current_section not in data:
                data[current_section] = {}
            data[current_section][key] = value
        else:
            if "global" not in data:
                data["global"] = {}
            data["global"][key] = value

    for query in queries:
        if not query.strip():
            continue
        section, key = query.strip().split(".")
        section_lower = section.lower()
        key_lower = key.lower()
        section_data = data.get(section_lower, {})
        value = section_data.get(key_lower, "NOT FOUND")
        print(value)


if __name__ == "__main__":
    main()
